/*
 * THE ASSET LIST - the only place that knows about artwork files.
 * All art is generated by tools/blender/render_assets.py + tools/compose_sheets.py (see CREDITS.md).
 *
 *   width  = displayed width in game pixels (height follows the aspect ratio)
 *   scale  = alternative to width: plain scale factor
 *   origin = [x, y] anchor (0..1)
 */
(function () {
  const NS = (window.OUTPOST = window.OUTPOST || {});

  const BUILDING_IDS = ['crew', 'oxygen', 'solar', 'shelter', 'greenhouse', 'battery', 'ice'];
  const CREW_COLORS = ['blueberry', 'bluey', 'coral', 'lavender', 'sage'];

  const images = {
    // backdrops (1920x1080 art shown at 1280x720)
    'bg.sky': { path: 'assets/environment/sky_nebula.png', width: 1280, origin: [0, 0] },
    'bg.title.planet': { path: 'assets/environment/title_planet.png', width: 620 },
    'bg.map.equator': { path: 'assets/environment/map_equator.png', width: 1280, origin: [0, 0] },
    'bg.map.pole': { path: 'assets/environment/map_pole.png', width: 1280, origin: [0, 0] },
    'bg.map.mars': { path: 'assets/environment/map_mars.png', width: 1280, origin: [0, 0] },
    'bg.site.equator': { path: 'assets/environment/site_equator.png', width: 1280, origin: [0, 0] },
    'bg.site.pole': { path: 'assets/environment/site_pole.png', width: 1280, origin: [0, 0] },
    'bg.site.mars': { path: 'assets/environment/site_mars.png', width: 1280, origin: [0, 0] },
    'bg.earth': { path: 'assets/environment/earth.png', width: 120 },
  };

  // buildings: building.<id>.<idle|ready>  (idle = switched off / unpowered, ready = running)
  BUILDING_IDS.forEach((id) => ['idle', 'ready'].forEach((v) => {
    images[`building.${id}.${v}`] = { path: `assets/buildings/${id}_${v}.png`, scale: 0.56, origin: [0.5, 0.86] };
  }));

  // character portraits: char.<who>.<expression>
  ['coral', 'sage', 'lavender'].forEach((c) => ['happy', 'worried', 'tired'].forEach((e) => {
    images[`char.${c}.${e}`] = { path: `assets/characters/${c}_${e}.png` };
  }));
  ['happy', 'talk', 'wow', 'worried'].forEach((e) => { images[`char.astro.${e}`] = { path: `assets/characters/astro_${e}.png` }; });

  // astronauts: 2048x512 sheets, 8 x 2 frames of 256px. row 1 = idle, row 2 = walk
  const spritesheets = {};
  CREW_COLORS.forEach((c) => {
    spritesheets[`astro.${c}`] = {
      path: `assets/astronauts/${c}.png`, frameWidth: 256, frameHeight: 256,
      idle: { start: 0, end: 7, fps: 6 }, walk: { start: 8, end: 15, fps: 11 },
      scale: 0.44, origin: [0.5, 0.9],
    };
  });

  NS.ASSETS = { images, spritesheets, walkSpeed: 120, BUILDING_IDS };
  NS.meta = (key) => images[key] || spritesheets[key] || {};
})();
